{"content": "#!/usr/bin/env python3
"""
Build 'Tomorrow Is Still Open' — rebranded title, acknowledgment page, TOC with page numbers.
Fixed anchor placement for all TOC entries.
"""
import re, os, base64, shutil, zipfile
from pathlib import Path
from datetime import datetime

SOURCE_PATH = Path("/home/bob/.hermes/cache/documents/doc_e21236c1f318_THE_UNWRITTEN_FUTURE_FINAL 3.md")
NEW_SECTION_PATH = Path("/home/bob/.hermes/cache/documents/doc_e4e1cac0981a_1 the_future_after_bob_final_section_20_30_pages.md")
COVER_PATH = Path("/home/bob/books/The_Unwritten_Future/Tomorrow_is_Still_Open_Cover.png")
OUTPUT_DIR = Path("/home/bob/books/The_Unwritten_Future/output")
OUTPUT_DIR.mkdir(exist_ok=True)

BOOK_TITLE = "Tomorrow Is Still Open"
BOOK_SUBTITLE = "A Memoir by Robert Mills"
FILE_PREFIX = "Tomorrow_is_Still_Open"
ACK_TEXT = "I would like to thank my wife, our children, stepchildren, grandchildren, step-grandchildren, and step great-grandchild, along with the friends, colleagues, leaders, coworkers, and employees whose presence and influence helped shape the life remembered in these pages."

with open(SOURCE_PATH) as f: manuscript = f.read()
with open(NEW_SECTION_PATH) as f: new_section = f.read()

# Add transition and new section
last_line_marker = "willingness to touch the outlet anyway"
if last_line_marker in manuscript:
    idx = manuscript.rfind(last_line_marker)
    end_idx = manuscript.find('\n', idx)
    if end_idx == -1: end_idx = len(manuscript)
    main_body = manuscript[:end_idx].strip()
    transition = "\n---\n\n## The Threshold\n\nBob closes the document. Cindy is calling from downstairs. Dinner is on the table. The evening stretches ahead — ordinary, precious, irreplaceable.\n\nBut a story this size does not end at a dinner table. A life that touched outlets and orbits, that built boats and systems and families, that survived the death of one love and found another — such a life leaves a wake that travels forward. The children of that life will have children. The machines Bob helped build will build machines of their own. The future he could only imagine will become someone else's morning coffee.\n\nThe epilogue is written. But there is one more story to tell. Not a look backward, as epilogues do. A look forward, as Bob always did.\n\nWhat follows is not Bob's memory. It is Bob's imagination — offered to the generations who will inherit what he could only dream of building. These are stories from a shore he will not reach, written for the hands that will hold the tools after his are still.\n\n---\n"
    manuscript = main_body + "\n\n" + transition + "\n\n" + new_section
    print("✅ Transition added after epilogue ending")
else:
    transition = "\n---\n\n## The Threshold\n\nBob closes the document...\n---\n"
    manuscript = manuscript.strip() + "\n\n" + transition + new_section

# Replace old title references in manuscript
manuscript = manuscript.replace("The Future is Unwritten", BOOK_TITLE)

# Save manuscript
updated_path = OUTPUT_DIR / f"{FILE_PREFIX}_Final.md"
with open(updated_path, "w") as f: f.write(manuscript)
print(f"✅ Final manuscript saved: {len(manuscript.split()):,} words")

# ============================================================
# Build TOC entries
# ============================================================
toc_entries = []
anchor_id_map = {}  # id -> (ttype, title)
id_counter = 0

for line in manuscript.split('\n'):
    s = line.strip()
    m1 = re.match(r'^# (Part \w+: .+)$', s)
    if m1: toc_entries.append(('part', m1.group(1))); continue
    m2 = re.match(r'^## (Chapter \w+: .+)$', s)
    if m2: toc_entries.append(('chapter', m2.group(1))); continue
    if s == '# Epilogue: The Unwritten Future':
        toc_entries.append(('epilogue', s[2:].strip())); continue

toc_entries.append(('final', 'Final Section: The Future After Bob'))

known_subs = ['The Empty Chair', 'The Children of the Assistant Age',
              'The Day the System Woke Up', 'The Age of Artificial General Organizations',
              'The New Work', 'The Robots at the Table',
              'The War of the Small Machines', 'The Quantum Year',
              'The New Map of Power', 'The Heat and the Water',
              'The Moon Underfoot', 'The First Child Born Off Earth',
              'Love in the Augmented World', 'The Letter Bob Could Not Send',
              'The Last Workshop', 'What Remains']

for line in new_section.split('\n'):
    s = line.strip()
    m = re.match(r'^## (.+)$', s)
    if m and m.group(1) in known_subs:
        toc_entries.append(('sub', m.group(1)))

# Assign anchor IDs
for i, (ttype, title) in enumerate(toc_entries):
    anchor_id_map[f"toc-{i}"] = title

print(f"📋 TOC entries: {len(toc_entries)}")

def esc(text):
    return text.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

# ============================================================
# Convert markdown to HTML body
# ============================================================
def inline(text):
    text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
    text = re.sub(r'\*(.+?)\*', r'<em>\1</em>', text)
    return text

def md_to_html(text):
    lines = text.split('\n')
    result = []
    in_ul = False
    in_quote = False

    for raw in lines:
        s = raw.strip()
        if not s:
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(''); continue
        if s in ('---', '___', '***'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append('<hr>'); continue
        if re.match(r'^# Part \w+:', s):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h2 class="part-title" id="ANCHOR-{len(toc_entries):03d}">{esc(s[2:].strip())}</h2>'); continue
        if re.match(r'^## Chapter \w+:', s):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h3 id="ANCHOR-{len(toc_entries):03d}">{esc(s[3:].strip())}</h3>'); continue
        if s.startswith('# Epilogue'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h2 class="epilogue-title" id="ANCHOR-{len(toc_entries):03d}">{esc(s[2:].strip())}</h2>'); continue
        if s.startswith('# Final Section'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h2 class="final-section-title" id="ANCHOR-{len(toc_entries):03d}">{esc(s[2:].strip())}</h2>'); continue
        if s.startswith('## '):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h4 id="ANCHOR-{len(toc_entries):03d}">{esc(s[3:].strip())}</h4>'); continue
        if s.startswith('### '):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<h5>{esc(s[4:].strip())}</h5>'); continue
        if s.startswith('### Transition'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append('<hr class="transition">'); continue
        if s.startswith('- ') or s.startswith('* '):
            if in_quote: result.append('</blockquote>'); in_quote = False
            if not in_ul: result.append('<ul>'); in_ul = True
            result.append(f'<li>{inline(s[2:])}</li>'); continue
        if s.startswith('>'):
            if in_ul: result.append('</ul>'); in_ul = False
            if not in_quote: result.append('<blockquote>'); in_quote = True
            result.append(f'<p>{inline(s[1:].strip())}</p>'); continue
        if re.match(r'^\*\*.+\*\*$', s) and len(s) < 80:
            if in_ul: result.append('</ul>'); in_ul = False
            if in_quote: result.append('</blockquote>'); in_quote = False
            result.append(f'<p class="section-heading">{inline(s)}</p>'); continue
        if in_ul: result.append('</ul>'); in_ul = False
        if in_quote: result.append('</blockquote>'); in_quote = False
        result.append(f'<p>{inline(s)}</p>')
    if in_ul: result.append('</ul>')
    if in_quote: result.append('</blockquote>')
    return '\n'.join(result)

body_html = md_to_html(manuscript)

# Now replace ANCHOR-NNN with actual toc-N anchors for matching TOC entries
# We process in reverse order to keep indices stable
# First, count occurrences of id="ANCHOR-XXX"
lines = body_html.split('\n')

# Strategy: walk the body and match headings to TOC entries in order
toc_idx = 0
new_lines = []
for line_num, line in enumerate(lines):
    if 'ANCHOR-' in line:
        # This is a heading that needs an anchor
        if toc_idx < len(toc_entries):
            real_id = f"toc-{toc_idx}"
            line = line.replace(f'ANCHOR-{len(toc_entries):03d}', real_id, 1)
            toc_idx += 1
        else:
            # More headings than TOC entries - just assign generic
            line = line.replace(f'ANCHOR-{len(toc_entries):03d}', 'toc-extra', 1)
    new_lines.append(line)
body_html = '\n'.join(new_lines)

print(f"📌 Anchors assigned: {toc_idx} (of {len(toc_entries)} TOC entries)")

# Encode cover
cover_b64 = ""
if COVER_PATH.exists():
    with open(COVER_PATH, "rb") as f: cover_b64 = base64.b64encode(f.read()).decode()

# Build TOC HTML with page numbers via target-counter
toc_html_lines = ['<div class="toc-page"><h2>Contents</h2><ul>']
for idx, (ttype, title) in enumerate(toc_entries):
    css_class = f"toc-{ttype}"
    entry_html = f'<li class="{css_class}"><a href="#toc-{idx}">{esc(title)}</a></li>'
    toc_html_lines.append(entry_html)
toc_html_lines.append('</ul></div>')

# Build full HTML
html = f'''<!DOCTYPE html><html lang="en">
<head>
<meta charset="UTF-8">
<title>{BOOK_TITLE}</title>
<style>
@page {{ size: 6in 9in; margin: 0.9in 0.85in;
    @top-center {{ content: "{BOOK_TITLE}"; font-family: 'Times New Roman', Times, serif; font-size: 8pt; color: #999; }}
    @bottom-center {{ content: counter(page); font-family: 'Times New Roman', Times, serif; font-size: 9pt; color: #666; }}
